-- Synthetic, password-free fixtures; every change is rolled back.
begin;
create temp table fixture(actor uuid default gen_random_uuid(), outsider uuid default gen_random_uuid(),company uuid default gen_random_uuid(),other_company uuid default gen_random_uuid(),job uuid default gen_random_uuid(),candidate uuid default gen_random_uuid(),request uuid default gen_random_uuid());
insert into fixture default values;
grant select on fixture to authenticated,service_role;
create temp table results(name text,passed boolean);
grant insert,select on results to authenticated,service_role;
create function pg_temp.ok(name text,passed boolean) returns void language plpgsql as $$begin if passed is distinct from true then raise exception 'FAILED: %',name;end if;insert into results values(name,true);end$$;
create function pg_temp.denied(name text,statement text,expected text) returns void language plpgsql as $$begin begin execute statement;exception when others then if sqlstate<>expected then raise exception 'FAILED wrong SQLSTATE %: % (%)',sqlstate,name,sqlerrm;end if;insert into results values(name,true);return;end;raise exception 'FAILED unexpectedly allowed: %',name;end$$;
insert into auth.users(id,email,role,aud) select id,id::text||'@ranking-test.invalid','authenticated','authenticated' from fixture,lateral unnest(array[actor,outsider]) id;
insert into public.companies(id,name) select company,'Ranking A' from fixture union all select other_company,'Ranking B' from fixture;
insert into public.company_members(company_id,user_id,role) select company,actor,'owner' from fixture union all select other_company,outsider,'owner' from fixture;
insert into public.jobs(id,company_id,titulo,descricao,criteria) select job,company,'Analista SQL','Atendimento de sistemas SQL.','[{"kind":"skill","text":"SQL","required":true,"weight":5,"min_years":null,"source":null}]' from fixture;
update public.jobs set approved_hash=private.job_hash(private.job_payload(titulo,descricao,categoria,criteria)) where id=(select job from fixture);
insert into public.candidates(id,company_id,processing_status,review_status,dados_extraidos) select candidate,company,'concluido','completed','{"nome_completo":"Revisado","skills":["SQL"]}' from fixture;
insert into public.candidates(company_id,processing_status,review_status,dados_extraidos) select company,'concluido','pending','{"nome_completo":"Revisão pendente"}'::jsonb from fixture union all select company,'erro','pending','{"nome_completo":"Leitura falha"}' from fixture union all select other_company,'concluido','completed','{"nome_completo":"Outra empresa"}' from fixture;
set local role service_role;
select set_config('test.run',public.begin_ranking(actor,company,job,request)->>'id',true) from fixture;
select pg_temp.ok('snapshot contains entire authorized base and excludes pending finals',(select total=3 and eligible=1 from public.ranking_runs where id=current_setting('test.run')::uuid));
select pg_temp.ok('pending reasons distinguish review and read failure',(select count(*)=2 and count(distinct reason)=2 from public.ranking_entries where run_id=current_setting('test.run')::uuid and reason is not null));
select pg_temp.ok('same request reuses exactly one run',(select public.begin_ranking(actor,company,job,request)->>'id'=current_setting('test.run') from fixture));
select pg_temp.denied('different simultaneous run blocked',$q$select public.begin_ranking(actor,company,job,gen_random_uuid()) from fixture$q$,'55000');
select pg_temp.denied('incomplete result cannot publish',$q$select public.finish_ranking(actor,current_setting('test.run')::uuid) from fixture$q$,'22023');
select public.stage_ranking(actor,current_setting('test.run')::uuid,jsonb_build_array(jsonb_build_object('candidate_id',candidate,'score',80,'details',jsonb_build_object('formula','evidence-v3')))) from fixture;
select public.finish_ranking(actor,current_setting('test.run')::uuid) from fixture;
select public.finish_ranking(actor,current_setting('test.run')::uuid) from fixture;
select pg_temp.ok('repeat finish does not duplicate scores',(select count(*)=1 and bool_and(score=80 and review_version=0 and run_id=current_setting('test.run')::uuid) from public.candidate_scores where company_id=(select company from fixture)));
select pg_temp.ok('historical extraction effective data and review preserved',(select snapshot->'dados_extraidos'->'skills'='["SQL"]' and snapshot ? 'correcoes_rh' and snapshot ? 'review_version' and documents='[]' from public.ranking_entries where run_id=current_setting('test.run')::uuid and candidate_id=(select candidate from fixture)));
select set_config('test.next',public.begin_ranking(actor,company,job,gen_random_uuid())->>'id',true) from fixture;
select pg_temp.denied('invalid score rejected before publication',$q$select public.stage_ranking(actor,current_setting('test.next')::uuid,jsonb_build_array(jsonb_build_object('candidate_id',candidate,'score',101,'details',jsonb_build_object('formula','evidence-v3')))) from fixture$q$,'23514');
select pg_temp.ok('previous ranking remains while new run incomplete',(select count(*)=1 and bool_and(score=80) from public.candidate_scores where company_id=(select company from fixture)));
select public.stage_ranking(actor,current_setting('test.next')::uuid,jsonb_build_array(jsonb_build_object('candidate_id',candidate,'score',77,'details',jsonb_build_object('formula','evidence-v3')))) from fixture;
reset role;
-- Force an actual insertion failure after DELETE, proving transaction rollback.
create function pg_temp.reject_score() returns trigger language plpgsql as $$begin if new.score=77 then raise exception 'Synthetic persistence failure';end if;return new;end$$;
create trigger test_reject_score before insert on public.candidate_scores for each row execute function pg_temp.reject_score();
set local role service_role;
select pg_temp.denied('write failure rolls back the replacement',$q$select public.finish_ranking(actor,current_setting('test.next')::uuid) from fixture$q$,'P0001');
select pg_temp.ok('failed replacement keeps old scores and completed history',(select count(*)=1 and bool_and(score=80 and run_id=current_setting('test.run')::uuid) from public.candidate_scores where company_id=(select company from fixture)) and (select count(*)=1 from public.ranking_runs where company_id=(select company from fixture) and status='completed'));
reset role;
drop trigger test_reject_score on public.candidate_scores;
update public.candidates set review_version=review_version+1 where id=(select candidate from fixture);
set local role service_role;
select pg_temp.denied('review change during calculation prevents publication',$q$select public.finish_ranking(actor,current_setting('test.next')::uuid) from fixture$q$,'40001');
select pg_temp.ok('review change marks scores and history stale',(select bool_and(stale) from public.ranking_runs where id=current_setting('test.run')::uuid) and (select bool_and(stale) from public.candidate_scores where company_id=(select company from fixture)));
select public.fail_ranking(actor,current_setting('test.next')::uuid) from fixture;
reset role;
-- Over the default REST page limit; database snapshot must not silently truncate.
insert into public.candidates(company_id,processing_status,review_status,dados_extraidos) select company,'concluido','completed','{"skills":["SQL"]}' from fixture,generate_series(1,1001);
set local role service_role;
select set_config('test.large',public.begin_ranking(actor,company,job,gen_random_uuid())->>'id',true) from fixture;
select pg_temp.ok('all 1004 authorized candidates captured',(select total=1004 and eligible=1002 from public.ranking_runs where id=current_setting('test.large')::uuid));
do $$declare batch jsonb;begin for batch in select jsonb_agg(jsonb_build_object('candidate_id',candidate_id,'score',90,'details',jsonb_build_object('formula','evidence-v3'))) from (select candidate_id,((row_number() over(order by candidate_id))-1)/200 as page from public.ranking_entries where run_id=current_setting('test.large')::uuid and reason is null) e group by page loop perform public.stage_ranking((select actor from fixture),current_setting('test.large')::uuid,batch);end loop;end$$;
select public.finish_ranking(actor,current_setting('test.large')::uuid) from fixture;
select pg_temp.ok('all 1002 eligible candidates published atomically',(select count(*)=1002 and bool_and(score=90) from public.candidate_scores where company_id=(select company from fixture)));
select pg_temp.ok('previous history survives replacement',(select count(*)=1 and bool_and(score=80) from public.ranking_entries where run_id=current_setting('test.run')::uuid and reason is null));
reset role;
update public.jobs set descricao='Escopo alterado para conferir novamente.' where id=(select job from fixture);
select pg_temp.ok('job change marks latest history stale',(select stale from public.ranking_runs where id=current_setting('test.large')::uuid));
select set_config('request.jwt.claims',json_build_object('sub',outsider,'role','authenticated')::text,true) from fixture;
set local role authenticated;
select pg_temp.ok('other company cannot read any history',(select count(*)=0 from public.ranking_runs) and (select count(*)=0 from public.ranking_entries));
select pg_temp.denied('browser cannot manufacture scores',$q$select public.stage_ranking(actor,current_setting('test.large')::uuid,'[]') from fixture$q$,'42501');
reset role;
delete from public.company_members where company_id=(select company from fixture) and user_id=(select actor from fixture);
set local role service_role;
select pg_temp.denied('revoked actor cannot repeat completed request',$q$select public.begin_ranking(actor,company,job,request) from fixture$q$,'42501');
reset role;
select json_build_object('passed',count(*),'tests',json_agg(name)) as results from results;
rollback;
